def transform(g):
    h=len(g); w=len(g[0])
    seen=set(); comps=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=0 and (i,j) not in seen:
                col=g[i][j]; st=[(i,j)]; seen.add((i,j)); px=[]
                while st:
                    r,c=st.pop(); px.append((r,c))
                    for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                        if 0<=nr<h and 0<=nc<w and g[nr][nc]==col and (nr,nc) not in seen:
                            seen.add((nr,nc)); st.append((nr,nc))
                comps.append((col,px))
    def straight(px): return len({r for r,_ in px})==1 or len({c for _,c in px})==1
    def ratio(px):
        rs=[r for r,_ in px]; cs=[c for _,c in px]
        return (max(cs)-min(cs)+1)/w if min(rs)==max(rs) else (max(rs)-min(rs)+1)/h
    def span(px):
        rs=[r for r,_ in px]; cs=[c for _,c in px]
        return max(max(rs)-min(rs)+1,max(cs)-min(cs)+1)
    lines=[cc for cc in comps if straight(cc[1]) and ratio(cc[1])>=0.5]
    ref=max(lines,key=lambda cc:span(cc[1]))[1]; refset=set(ref)
    col,px=[cc for cc in comps if set(cc[1]).isdisjoint(refset)][0]
    r0=min(r for r,_ in px); r1=max(r for r,_ in px)
    c0=min(c for _,c in px); c1=max(c for _,c in px)
    oh=r1-r0+1; ow=c1-c0+1
    vertical=len({c for _,c in ref})==1
    out=[[0]*w for _ in range(h)]
    if vertical:
        nr=h-oh if r0 < h-1-r1 else 0; nc=c0
    else:
        nr=r0; nc=w-ow
    for r,c in px: out[nr+r-r0][nc+c-c0]=col
    return out

